<?php

declare(strict_types=1);require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/face_service.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');$s=db()->prepare('SELECT * FROM photos WHERE id=?');$s->execute([$id]);$photo=$s->fetch();if(!$photo)throw new RuntimeException('ไม่พบรูป');if($action==='toggle')db()->prepare('UPDATE photos SET is_visible=1-is_visible WHERE id=?')->execute([$id]);elseif($action==='reindex'){$absolute=dirname(__DIR__).'/'.$photo['local_path'];$r=face_index_photo((int)$photo['event_id'],$id,$absolute);db()->prepare('UPDATE photos SET face_indexed=? WHERE id=?')->execute([(int)($r['faces']??0)>0?1:0,$id]);}audit('photo_'.$action,(string)$id);flash('success','ดำเนินการแล้ว');redirect('admin/photos.php');}catch(Throwable $e){flash('error',$e->getMessage());redirect('admin/photos.php');}}$eventId=filter_input(INPUT_GET,'event',FILTER_VALIDATE_INT);$sql='SELECT p.*,e.title event_title FROM photos p JOIN events e ON e.id=p.event_id';$params=[];if($eventId){$sql.=' WHERE p.event_id=?';$params[]=$eventId;}$sql.=' ORDER BY p.id DESC LIMIT 300';$s=db()->prepare($sql);$s->execute($params);$photos=$s->fetchAll();$events=db()->query('SELECT id,title FROM events ORDER BY title')->fetchAll();page_header('รูปภาพ',true);require __DIR__.'/_nav.php';?><h1>จัดการรูปภาพ</h1><form method="get" class="actions"><select name="event"><option value="">ทุกกิจกรรม</option><?php foreach($events as $event):?><option value="<?=(int)$event['id']?>" <?=$eventId===(int)$event['id']?'selected':''?>><?=e($event['title'])?></option><?php endforeach?></select><button class="btn">กรอง</button></form><div class="photo-grid" style="margin-top:18px"><?php foreach($photos as $photo):?><article class="photo"><img loading="lazy" src="<?=e(url($photo['local_path']))?>" alt="<?=e($photo['file_name'])?>"><div class="meta"><strong><?=e($photo['file_name'])?></strong><p class="muted"><?=e($photo['event_title'])?></p><p><span class="badge"><?=$photo['is_visible']?'แสดง':'ซ่อน'?></span> <span class="badge"><?=$photo['face_indexed']?'มีดัชนี':'ไม่มีดัชนี'?></span></p><div class="actions"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$photo['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn secondary"><?=$photo['is_visible']?'ซ่อน':'แสดง'?></button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$photo['id']?>"><input type="hidden" name="action" value="reindex"><button class="btn">ทำดัชนีใหม่</button></form></div></div></article><?php endforeach?></div><?php page_footer();?>
